import { useState } from 'react';
import { getSourceCodenames } from '../data/sources';

export default function useNormalFlightSearch() {
  const [flightData, setFlightData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [selectedDateRange, setSelectedDateRange] = useState(null);
  const [selectedFlights, setSelectedFlights] = useState(null);
  const [pricingData, setPricingData] = useState(null);

  const generateRouteCombinations = (path) => {
    // Split the path into segments
    const segments = path.split('-');
    console.log('Path segments:', segments);

    // Process each segment to handle grouped airports
    const processedSegments = segments.map(segment => {
      if (segment.includes('/')) {
        return segment.split('/');
      }
      return [segment];
    });
    console.log('Processed segments:', processedSegments);

    // Generate individual route segments
    const combinations = [];
    for (let i = 0; i < processedSegments.length - 1; i++) {
      const fromAirports = processedSegments[i];
      const toAirports = processedSegments[i + 1];

      fromAirports.forEach(from => {
        toAirports.forEach(to => {
          combinations.push(`${from}-${to}`);
        });
      });
    }

    console.log('Generated combinations:', combinations);
    return combinations;
  };

  const processFlightData = (data, routeCombinations) => {
    console.log('Processing flight data:', data);
    console.log('Route combinations:', routeCombinations);

    // Group flights by date and route
    const flightsByDate = {};

    data.forEach(flight => {
      const date = flight.date;
      const route = `${flight.originAirport}-${flight.destinationAirport}`;

      // Only process flights that match our route combinations
      if (routeCombinations.includes(route)) {
        if (!flightsByDate[date]) {
          flightsByDate[date] = {};
        }

        if (!flightsByDate[date][route]) {
          flightsByDate[date][route] = {
            route,
            classes: {
              Y: { available: flight.YAvailable, direct: flight.YDirect, airlines: flight.YAirlines },
              W: { available: flight.WAvailable, direct: flight.WDirect, airlines: flight.WAirlines },
              J: { available: flight.JAvailable, direct: flight.JDirect, airlines: flight.JAirlines },
              F: { available: flight.FAvailable, direct: flight.FDirect, airlines: flight.FAirlines }
            }
          };
        }
      }
    });

    console.log('Processed flights by date:', flightsByDate);
    return flightsByDate;
  };

  const handleSearch = async (searchParams) => {
    const { path, sourcesExcluded, apiKey, dateRange } = searchParams;
    console.log('Search params:', searchParams);

    // Reset errors
    setErrors({});

    // Validate mandatory fields
    if (!path) {
      setErrors({ path: 'Path is required' });
      return;
    }

    // Validate path format
    const pathSegments = path.split(/[/-]/);
    if (pathSegments.length < 2) {
      setErrors({ path: 'Invalid path format' });
      return;
    }

    // Generate all possible route combinations
    const routeCombinations = generateRouteCombinations(path);

    // Get all available source codenames and exclude the ones selected by user
    const allSources = getSourceCodenames();
    const includedSources = allSources.filter(source => !sourcesExcluded.includes(source));
    console.log('Included sources:', includedSources);

    setIsLoading(true);
    try {
      const response = await fetch('https://backend-284998006367.us-central1.run.app/api/availability-v2', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Partner-Authorization': apiKey
        },
        body: JSON.stringify({
          routeId: path,
          startDate: dateRange[0],
          endDate: dateRange[1],
          sources: includedSources.join(',')
        })
      });

      if (!response.ok) {
        throw new Error('Search failed');
      }

      const data = await response.json();
      console.log('API response:', data);
      const processedData = processFlightData(data, routeCombinations);
      setFlightData(processedData);
      setSelectedDateRange(dateRange);
    } catch (error) {
      console.error('Search failed:', error);
      setErrors({ general: 'Search failed. Please try again.' });
    } finally {
      setIsLoading(false);
    }
  };

  const handleDateRangeSelect = (dateRange) => {
    setSelectedDateRange(dateRange);
  };

  const handleFlightSelect = (flights, pricing) => {
    setSelectedFlights(flights);
    setPricingData(pricing);
  };

  return {
    flightData,
    isLoading,
    handleSearch,
    errors,
    selectedDateRange,
    handleDateRangeSelect,
    selectedFlights,
    handleFlightSelect,
    pricingData
  };
}
